            {
                "auth" => "（API Key 无效，请检查模型连接）",
                "timeout" => "（模型响应超时了，让我歇口气~）",
                _ => "（模型连接出错了）",
            }));
            return;
        }
        catch (Exception)
        {
            OnUiThread(() => _chatWindow.AppendAssistantAsync("（出错了，请稍后再试）"));
            return;
        }

        // UI 输出在串行段外（不延长锁持有；Speech 等同样移出）
