            return new HotkeySettingsUpdateResult(
                false,
                current,
                message,
                rollbackComplete,
                rollback,
                persistenceError);
        }
    }

    public static string DescribeRuntimeFailure(HotkeyApplyResult result)
    {
        if (result.Phase == "validation")
        {
            if (result.ValidationIssues.Any(issue => issue.Code == "duplicate"))
                return "快捷键重复，请为每个动作设置不同组合";
            return "快捷键组合无效，主键必须搭配 Ctrl、Alt、Shift 或 Win";
        }

        var action = result.FailedAction switch
        {
            HotkeyAction.TogglePets => "显示或隐藏宠物",
            HotkeyAction.ToggleMode => "切换输出模式",
            HotkeyAction.OpenSettings => "打开设置",
            HotkeyAction.Quit => "退出应用",
            _ => "快捷键",
        };
        var reason = result.NativeError == 1409
            ? "已被其他程序占用"
            : $"系统错误 {result.NativeError}";
        var rollback = result.RollbackComplete ? "旧快捷键保持不变" : "旧快捷键未能完整恢复";
        return $"{action}注册失败：{reason}；{rollback}";
    }
}

